custom_fields.content:
[[[
  const source = entity;
  const stateVal = source?.state;
  const rawValue = Number.parseFloat(stateVal);
  const unit = source?.attributes?.unit_of_measurement;
  const value = unit === '°F' ? (rawValue - 32) * 5 / 9 : rawValue;
  const known = Number.isFinite(value);
  const maximum = Number(variables.max_value) || 100;
  const width = known ? Math.max(0, Math.min(100, Math.abs(value) / maximum * 100)) : 0;
  const accent = variables.accent || '#42a5f5';
  const icon = this._config.icon || source?.attributes?.icon || 'mdi:flash';
  const name = this._config.name || source?.attributes?.friendly_name || '';
  let formatted = '—';
  if (source && known) {
    if (hass.formatEntityState) {
      formatted = hass.formatEntityState(source);
    } else {
      formatted = `${source.state} ${source.attributes?.unit_of_measurement ?? ''}`;
    }
  } else if (source?.state && !['unknown', 'unavailable', 'null'].includes(source.state)) {
    formatted = `${source.state} ${source.attributes?.unit_of_measurement ?? ''}`;
  }
  if (known && unit === 'V') formatted = `${new Intl.NumberFormat('ru', {maximumFractionDigits:3}).format(value)} V`;
  if (known && (unit === '°F' || unit === '°C')) formatted = `${new Intl.NumberFormat('ru', {maximumFractionDigits:1}).format(value)} °C`;
  const sub = variables.subtext ? `<div style="color:rgba(255,255,255,.52);font-size:11.5px;line-height:1.1;margin-top:2px">${variables.subtext}</div>` : '';
  return `
    <div style="display:grid;grid-template-columns:minmax(0,1fr) 50px;grid-template-rows:auto 1fr auto;column-gap:12px;row-gap:7px;width:100%;height:100%;box-sizing:border-box;text-align:left">
      <div style="grid-column:1;grid-row:1;color:rgba(255,255,255,.64);font-size:13px;font-weight:500;line-height:1.2;white-space:normal;overflow-wrap:anywhere">${name}</div>
      <div style="grid-column:1;grid-row:2;align-self:center">
        <div style="color:#f7f7f7;font-size:clamp(21px,1.55vw,29px);font-weight:400;line-height:1;letter-spacing:-.6px;white-space:nowrap">${formatted}</div>
        ${sub}
      </div>
      <div style="grid-column:2;grid-row:1/3;align-self:center;justify-self:end;width:48px;height:48px;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.06);box-shadow:0 10px 22px rgba(0,0,0,.3),inset 0 1px 0 rgba(255,255,255,.08)"><ha-icon icon="${icon}" style="width:27px;color:${accent}"></ha-icon></div>
      <div style="grid-column:1/3;grid-row:3;height:9px;border-radius:99px;background:rgba(255,255,255,.09);overflow:hidden"><div style="width:${width}%;height:100%;border-radius:99px;background:${accent};box-shadow:0 0 16px ${accent};transition:width .7s ease"></div></div>
    </div>`;
]]]

[[[
  const stateVal = entity ? entity.state : undefined;
  const value = Number.parseFloat(stateVal);
  const known = Number.isFinite(value);
  const maximum = Number(variables.max_value) || 100;
  const width = known ? Math.max(0, Math.min(100, Math.abs(value) / maximum * 100)) : 0;
  const accent = variables.accent || '#55d6a9';
  const icon = this._config.icon || entity?.attributes?.icon || 'mdi:battery-high';
  const name = this._config.name || entity?.attributes?.friendly_name || 'Заряд АКБ (SOC)';
  const formatted = known ? `${value.toFixed(0)} %` : '—';

  const pwrState = hass.states['__PM_battery_power__'];
  const capState = hass.states['__PM_remaining_capacity__'];
  const voltState = hass.states['__PM_battery_voltage__'];
  const pwr = pwrState ? Number.parseFloat(pwrState.state) : 0;
  const cap = capState ? Number.parseFloat(capState.state) : 0;
  const volt = voltState ? Number.parseFloat(voltState.state) : 51.2;

  let timeSub = '';
  if (known && Number.isFinite(pwr) && Number.isFinite(cap) && cap > 0) {
    if (pwr < -25) {
      const dischargeWatts = Math.abs(pwr);
      const remainingWh = cap * (Number.isFinite(volt) && volt > 0 ? volt : 51.2);
      const hours = remainingWh / dischargeWatts;
      if (hours > 0 && hours < 200) {
        const h = Math.floor(hours);
        const m = Math.round((hours - h) * 60);
        timeSub = `~${h}ч ${m}мин до разряда`;
      }
    } else if (pwr > 25) {
      const socVal = value > 0 ? value : 50;
      const neededAh = cap * (100 - socVal) / Math.max(1, socVal);
      const neededWh = neededAh * (Number.isFinite(volt) && volt > 0 ? volt : 51.2);
      const hours = neededWh / pwr;
      if (hours > 0 && hours < 100) {
        const h = Math.floor(hours);
        const m = Math.round((hours - h) * 60);
        timeSub = `~${h}ч ${m}мин до 100%`;
      }
    } else {
      timeSub = 'Буферный режим';
    }
  }
  return `
    <div style="display:grid;grid-template-columns:minmax(0,1fr) 50px;grid-template-rows:auto 1fr auto;column-gap:12px;row-gap:7px;width:100%;height:100%;box-sizing:border-box;text-align:left">
      <div style="grid-column:1;grid-row:1;color:rgba(255,255,255,.64);font-size:13px;font-weight:500;line-height:1.2;white-space:normal;overflow-wrap:anywhere">${name}</div>
      <div style="grid-column:1;grid-row:2;align-self:center">
        <div style="color:#f7f7f7;font-size:clamp(21px,1.55vw,29px);font-weight:400;line-height:1;letter-spacing:-.6px;white-space:nowrap">${formatted}</div>
        ${timeSub ? `<div style="color:${accent};font-size:11.5px;font-weight:500;line-height:1.1;margin-top:3px">${timeSub}</div>` : ''}
      </div>
      <div style="grid-column:2;grid-row:1/3;align-self:center;justify-self:end;width:48px;height:48px;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.06);box-shadow:0 10px 22px rgba(0,0,0,.3),inset 0 1px 0 rgba(255,255,255,.08)"><ha-icon icon="${icon}" style="width:27px;color:${accent}"></ha-icon></div>
      <div style="grid-column:1/3;grid-row:3;height:9px;border-radius:99px;background:rgba(255,255,255,.09);overflow:hidden"><div style="width:${width}%;height:100%;border-radius:99px;background:${accent};box-shadow:0 0 16px ${accent};transition:width .7s ease"></div></div>
    </div>`;
]]]

[[[
  const on = entity?.state === 'on';
  const accent = entity?.entity_id?.startsWith('binary_sensor.')
    ? (on ? '#55d6a9' : '#ef6a73')
    : (variables.accent || '#42a5f5');
  const icon = this._config.icon || entity?.attributes?.icon || 'mdi:information-outline';
  const name = this._config.name || entity?.attributes?.friendly_name || '';
  let formatted = '—';
  if (entity) {
    if (hass.formatEntityState) {
      formatted = hass.formatEntityState(entity);
    } else {
      formatted = entity.state ?? '—';
    }
  }
  return `
    <div style="display:grid;grid-template-columns:48px minmax(0,1fr);grid-template-rows:1fr 1fr;column-gap:12px;width:100%;height:100%;box-sizing:border-box;text-align:left">
      <div style="grid-column:1;grid-row:1/3;align-self:center;width:46px;height:46px;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.06);box-shadow:inset 0 1px 0 rgba(255,255,255,.07)"><ha-icon icon="${icon}" style="width:25px;color:${accent}"></ha-icon></div>
      <div style="grid-column:2;grid-row:1;align-self:end;color:rgba(255,255,255,.62);font-size:12px;line-height:1.15;white-space:normal;overflow-wrap:anywhere">${name}</div>
      <div style="grid-column:2;grid-row:2;align-self:start;color:#f6f6f6;font-size:15px;font-weight:600;line-height:1.2;white-space:normal;overflow-wrap:anywhere">${formatted}</div>
    </div>`;
]]]

[[[
  const idx=Number(variables.index)||1;
  const voltagePattern='', resistancePattern='';
  const cellState=(field,index)=>hass.states[(field==='voltage'?variables.cell_entities:variables.resistance_entities)?.[index-1]];
  const state = entity?.state;
  const value = Number.parseFloat(state);
  const known = Number.isFinite(value);
  let cells = [];
  for (let i = 1; i <= 32; i++) {
    const s = cellState('voltage', i, voltagePattern);
    const v = s ? Number.parseFloat(s.state) : NaN;
    if (Number.isFinite(v)) cells.push(v);
  }
  const min = cells.length ? Math.min(...cells) : NaN;
  const max = cells.length ? Math.max(...cells) : NaN;
  const avg = cells.length ? cells.reduce((a, b) => a + b, 0) / cells.length : NaN;
  const spread = Number.isFinite(min) && Number.isFinite(max) ? max - min : 0;
  let accent = '#55d6a9';
  if (known && spread > 0.0005) {
    if (Math.abs(value - max) < 0.000001) accent = '#ff7043';
    else if (Math.abs(value - min) < 0.000001) accent = '#22d3ee';
  }
  const width = known && spread > 0.0005
    ? Math.max(4, Math.min(100, (value - min) / spread * 100))
    : (known ? 100 : 0);
  const dev = known && Number.isFinite(avg) ? (value - avg) * 1000 : null;
  const devText = dev === null ? '' : `${dev >= 0 ? '+' : '−'}${Math.abs(dev).toFixed(0)} mV к среднему`;
  const formatted = known ? `${value.toFixed(3)} V` : '—';
  const resState = cellState('resistance', idx, resistancePattern);
  const resVal = resState ? Number.parseFloat(resState.state) : NaN;
  const resText = Number.isFinite(resVal) ? `${resVal.toFixed(2)} mΩ` : '';
  return `
    <div style="display:grid;grid-template-rows:auto auto 1fr auto;row-gap:6px;width:100%;height:100%;box-sizing:border-box;text-align:left">
      <div style="color:rgba(255,255,255,.6);font-size:12.5px;font-weight:500;line-height:1.15">Ячейка ${idx}</div>
      <div style="color:#f7f7f7;font-size:clamp(20px,1.35vw,25px);font-weight:600;line-height:1;letter-spacing:-.4px;white-space:nowrap">${formatted}</div>
      <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;min-width:0">
        <span style="color:rgba(255,255,255,.5);font-size:11.5px;line-height:1.1;white-space:nowrap">${devText}</span>
        ${resText ? `<span style="color:rgba(255,255,255,.45);font-size:11.5px;font-weight:500;white-space:nowrap;letter-spacing:.1px;margin-left:auto">${resText}</span>` : ''}
      </div>
      <div style="height:7px;border-radius:99px;background:rgba(255,255,255,.09);overflow:hidden"><div style="width:${width}%;height:100%;border-radius:99px;background:${accent};box-shadow:0 0 12px ${accent};transition:width .7s ease"></div></div>
    </div>`;
]]]

balance.extra_styles:
@keyframes balance_wave {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}
@keyframes balance_card_pulse {
  0%, 100% {
    border-color: rgba(85,214,169,0.3);
    box-shadow: 0 14px 30px rgba(0,0,0,0.28), 0 0 16px rgba(85,214,169,0.12), inset 0 1px 0 rgba(255,255,255,0.08);
  }
  50% {
    border-color: rgba(85,214,169,0.6);
    box-shadow: 0 14px 30px rgba(0,0,0,0.28), 0 0 28px rgba(85,214,169,0.25), inset 0 1px 0 rgba(255,255,255,0.14);
  }
}

custom_fields.content:
[[[
  const valid=c=>['on','off'].includes(c?.state);
  const source=entity;
  const currentSource=hass.states[variables.current_entity];
  const current = Number.parseFloat(currentSource?.state);
  const binaryKnown = valid(source);
  const currentKnown = Number.isFinite(current);
  const on = binaryKnown ? source.state === 'on' : (currentKnown && Math.abs(current) >= 0.01);
  const unknown = !binaryKnown && !currentKnown;
  const accent = unknown ? 'rgba(255,255,255,.45)' : (on ? '#55d6a9' : '#7e57c2');
  const bmsName = variables.bms_name || 'BMS';
  const label = unknown ? `Нет данных · ${bmsName}` : (on ? `${bmsName}: балансировка активна` : `${bmsName}: балансировка не активна`);
  const sub = unknown ? `Проверьте связь с ${bmsName}` : (on ? `${bmsName} выравнивает ячейки прямо сейчас` : 'Разброс ячеек в пределах нормы');
  const icon = 'mdi:scale-balance';
  const iconBg = on && !unknown ? 'rgba(85,214,169,.15)' : 'rgba(255,255,255,.06)';
  const iconBorder = on && !unknown ? '1px solid rgba(85,214,169,.35)' : '1px solid rgba(255,255,255,.06)';
  const pillBg = unknown ? 'rgba(255,255,255,.07)' : (on ? 'rgba(85,214,169,.16)' : 'rgba(126,87,194,.13)');
  const pillBorder = on && !unknown ? '1px solid rgba(85,214,169,.35)' : '1px solid rgba(255,255,255,.06)';
  return `
    <div style="display:grid;grid-template-columns:44px minmax(0,1fr) auto;column-gap:13px;align-items:center;width:100%;height:100%;box-sizing:border-box;text-align:left">
      <div style="width:42px;height:42px;border-radius:50%;display:grid;place-items:center;background:${iconBg};border:${iconBorder};box-shadow:inset 0 1px 0 rgba(255,255,255,.1);box-sizing:border-box">
        <ha-icon icon="${icon}" style="width:23px;color:${accent};display:block"></ha-icon>
      </div>
      <div style="min-width:0">
        <div style="color:#f2f2f2;font-size:15px;font-weight:600;line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${label}</div>
        <div style="color:rgba(255,255,255,.52);font-size:12px;line-height:1.25;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${sub}</div>
      </div>
      <div style="justify-self:end;padding:5px 12px;border-radius:99px;background:${pillBg};border:${pillBorder};color:${accent};font-size:11.5px;font-weight:600;letter-spacing:.3px;white-space:nowrap;box-sizing:border-box">${unknown ? '—' : (on ? 'ON' : 'OFF')}</div>
    </div>`;
]]]

card.border:
[[[
  const on = entity?.state === 'on';
  return on ? '1px solid rgba(85,214,169,0.32)' : '1px solid rgba(255,255,255,0.055)';
